python3 - <<'EOF'
import pty, os, time, select

def run(cmd):
    pid, fd = pty.fork()
    if pid == 0:
        os.execvp(cmd[0], cmd)
    out = b""
    def wait_for(needle, timeout=10):
        nonlocal out
        t0 = time.time()
        while time.time() - t0 < timeout:
            r, _, _ = select.select([fd], [], [], 0.2)
            if r:
                try:
                    data = os.read(fd, 4096)
                except OSError:
                    return False
                if not data:
                    return False
                out += data
                if needle in out:
                    return True
        return False
    assert wait_for(b"Starting", 10), "no start output:\n" + out.decode(errors='replace')
    time.sleep(0.3)
    os.write(fd, b"\x03")                      # Ctrl-C -> debugger
    assert wait_for(b"(cdb)", 10), "no cdb prompt:\n" + out.decode(errors='replace')
    for cmdline, needle in [(b"mem 0 4\n", b"mem"), (b"step\n", None), (b"con\n", b"Results"), (b"", None)]:
        if cmdline: os.write(fd, cmdline)
    assert wait_for(b"Results", 15), "no results after con:\n" + out.decode(errors='replace')
    try: os.kill(pid, 9)
    except: pass
    return out.decode(errors='replace')

text = run(["/usr/local/bin/pmars", "-b", "-r", "500000", "-f", "flashpaper.red", "rave.red"])
print("=== LAST 800 CHARS ===")
print(text[-800:])
EOF

